function getExcerptsForBrief(
  jurisdiction: string,
  role:         string,
  tracks:       string[]
): Array<Excerpt & { track: string; trackLabel: string; trackIcon: string }> {
  return tracks
    .map((t) => {
      const excerpt  = EXCERPTS[jurisdiction]?.[role]?.[t];
      const trackDef = TRACKS.find((tk) => tk.value === t);
      if (!excerpt || !trackDef) return null;
      return { ...excerpt, track: t, trackLabel: trackDef.label, trackIcon: trackDef.icon };
    })
    .filter(Boolean) as Array<Excerpt & { track: string; trackLabel: string; trackIcon: string }>;
}

export default function BriefBuilder() {
  const [jurisdiction, setJurisdiction] = useState("");
  const [role,         setRole]         = useState("");
  const [tracks,       setTracks]       = useState<string[]>([]);
  const [briefShown,   setBriefShown]   = useState(false);

  const toggleTrack = (t: string) =>
    setTracks((prev) =>
      prev.includes(t) ? prev.filter((x) => x !== t) : [...prev, t]
    );

  const briefItems  = briefShown
    ? getExcerptsForBrief(jurisdiction, role, tracks)
    : [];

  const canGenerate = !!jurisdiction && !!role && tracks.length > 0;

  return (
    <div className="bg-card border border-fog rounded-2xl p-6 md:p-8">
      <div className="mb-6">
        <h3 className="font-display font-bold text-navy text-[18px] mb-1">
          Build your sample Intelligence Brief
        </h3>
        <p className="text-[13px] text-slate mb-5">
          Select your jurisdiction and role, then pick your topic tracks.
          We'll assemble a representative brief showing exactly the depth
          and format you'll receive every Monday — written for your role.
        </p>
        <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 mb-6">
          <div>
            <label className="block text-[11px] font-bold uppercase tracking-widest text-navy mb-1.5">
              Your jurisdiction
            </label>
            <select
              value={jurisdiction}
              onChange={(e) => { setJurisdiction(e.target.value); setBriefShown(false); }}
              className="w-full px-3.5 py-2.5 text-[13px] bg-paper border border-silver rounded-lg text-navy outline-none focus:border-blue focus:ring-1 focus:ring-blue transition-colors"
            >
              <option value="">Select your jurisdiction…</option>
              {JURISDICTIONS.map((j) => (
                <option key={j.value} value={j.value}>{j.label}</option>
              ))}
            </select>
          </div>
          <div>
            <label className="block text-[11px] font-bold uppercase tracking-widest text-navy mb-1.5">
              Your role
            </label>
            <select
              value={role}
              onChange={(e) => { setRole(e.target.value); setBriefShown(false); }}
              className="w-full px-3.5 py-2.5 text-[13px] bg-paper border border-silver rounded-lg text-navy outline-none focus:border-blue focus:ring-1 focus:ring-blue transition-colors"
            >
              <option value="">Select your role…</option>
              {ROLES.map((r) => (
                <option key={r.value} value={r.value}>{r.label}</option>
              ))}
            </select>
          </div>
        </div>
      </div>

      <div className="mb-6">
        <p className="text-[11px] font-bold uppercase tracking-widest text-navy mb-3">
          Select your topic tracks
        </p>
        <div className="grid grid-cols-1 md:grid-cols-2 gap-2.5">
          {TRACKS.map((track) => {
            const sel = tracks.includes(track.value);
            return (
              <button
                key={track.value}
                type="button"
                onClick={() => { toggleTrack(track.value); setBriefShown(false); }}
                className={`flex items-start gap-2.5 px-4 py-3 rounded-xl border text-left w-full transition-all cursor-pointer ${
                  sel
                    ? "bg-navy border-navy shadow-eup-sm"
                    : "bg-white border-fog hover:border-navy/40"
                }`}
              >
                <span className="text-[18px] flex-shrink-0 mt-0.5">{track.icon}</span>
                <div className="min-w-0 flex-1">
                  <p className={`text-[13px] font-semibold leading-tight ${sel ? "text-white" : "text-navy"}`}>
                    {track.label}
                  </p>
                  <p className={`text-[11px] mt-0.5 leading-snug ${sel ? "text-blue-200" : "text-slate"}`}>
                    {track.desc}
                  </p>
                </div>
                {sel && <Check className="w-4 h-4 text-white/70 flex-shrink-0 mt-0.5" />}
              </button>
            );
          })}
        </div>
        <p className="text-[12px] text-slate mt-3 text-center">
          {tracks.length === 0
            ? "Select one or more tracks above"
            : `${tracks.length} track${tracks.length > 1 ? "s" : ""} selected`}
        </p>
      </div>

      {!briefShown && (
        <div className="text-center mb-2">
          <button
            type="button"
            disabled={!canGenerate}
            onClick={() => setBriefShown(true)}
            className="px-8 py-3 rounded-xl text-[14px] font-bold bg-navy text-white hover:opacity-90 disabled:opacity-40 disabled:cursor-not-allowed transition-all"
          >
            Generate Brief →
          </button>
          {!canGenerate && (
            <p className="text-[12px] text-slate mt-2">
              Select jurisdiction, role, and at least one track to generate
            </p>
          )}
        </div>
      )}

      {briefShown && briefItems.length > 0 && (
        <div className="mt-2">
          <div className="bg-gradient-to-br from-navy to-steel rounded-xl p-5 mb-4">
            <div className="flex items-center gap-2 mb-3 flex-wrap">
              <span className="text-[9px] font-bold uppercase tracking-widest text-amber-400 bg-amber-400/10 border border-amber-400/20 px-2.5 py-0.5 rounded-full">
                ⭐ Your Intelligence Brief
              </span>
              <span className="text-blue-300/60 text-[10px]">
                {briefItems.length} article{briefItems.length > 1 ? "s" : ""} matched to your tracks
              </span>
            </div>
            <p className="text-blue-200/70 text-[12px] leading-relaxed">
              A representative sample showing the format and depth of your Monday brief — one article per selected track, written for{" "}
              {ROLES.find((r) => r.value === role)?.label ?? "your role"} in{" "}
              {JURISDICTIONS.find((j) => j.value === jurisdiction)?.label ?? "your jurisdiction"}.
            </p>
          </div>

          <div className="space-y-4">
            {briefItems.map((item) => (
              <div
                key={item.track}
                className="bg-gradient-to-br from-navy to-steel rounded-xl p-5 text-white"
              >
                <div className="flex items-center gap-1.5 mb-3">
                  <span className="text-[14px]">{item.trackIcon}</span>
                  <span className="text-[10px] font-bold uppercase tracking-widest text-blue-300/80">
                    {item.trackLabel}
                  </span>
                </div>
                <h4 className="font-display font-bold text-white text-[15px] leading-snug mb-2.5">
                  {item.headline}
                </h4>
                <p className="text-blue-100/80 text-[13px] leading-relaxed mb-3">
                  {item.excerpt}
                </p>
                <div className="bg-white/10 border border-white/15 rounded-lg px-4 py-3">
                  <p className="text-[10px] font-bold uppercase tracking-wider text-amber-400 mb-1">
                    🎯 Your action item
                  </p>
                  <p className="text-white/90 text-[13px] leading-relaxed">
                    {item.action}
                  </p>
                </div>
              </div>
            ))}
          </div>

          <div className="mt-5 p-5 bg-amber-400/10 border border-amber-400/20 rounded-xl text-center">
            <p className="text-[14px] font-semibold text-navy mb-1">
              This is your brief. Every Monday. Automatically.
            </p>
            <p className="text-[13px] text-slate mb-4">
              Every article in the real brief reflects that week's actual enforcement actions and regulatory developments — written for your role and jurisdiction.
            </p>
            <a
              href="#pro-plan-card"
              className="inline-block text-[13px] font-bold text-navy bg-amber-400 hover:opacity-90 transition-all px-6 py-2.5 rounded-xl no-underline"
              onClick={(e) => {
                e.preventDefault();
                document.getElementById("pro-plan-card")?.scrollIntoView({ behavior: "smooth" });
              }}
            >
              Get your Intelligence Brief →
            </a>
          </div>

          <div className="text-center mt-4">
            <button
              type="button"
              onClick={() => setBriefShown(false)}
              className="text-[12px] text-slate hover:text-navy underline underline-offset-2"
            >
              ← Change my selections
            </button>
          </div>
        </div>
      )}
    </div>
  );
}
